<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue';import {post,request} from '../api/client';import type {FileAsset} from '../api/types';import {errorText,notify} from '../ui';
const props=defineProps<{modelValue:FileAsset[];usage:'RESULT'|'INSPECTION';disabled?:boolean}>();const emit=defineEmits<{'update:modelValue':[files:FileAsset[]];blocked:[value:boolean]}>();
type Pending={id:string;file:File;url:string;status:'waiting'|'uploading'|'failed';error:string};const pending=ref<Pending[]>([]);const newlyUploaded=new Set<string>();
function report(){emit('blocked',pending.value.length>0);}
async function stripMetadata(file:File){const image=await createImageBitmap(file);try{const scale=Math.min(1,1600/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('当前浏览器无法处理图片');ctx.drawImage(image,0,0,canvas.width,canvas.height);const mime=file.type==='image/png'?'image/png':'image/jpeg';const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('图片处理失败')),mime,.86));return new File([blob],file.name.replace(/\.[^.]+$/,'')+(mime==='image/png'?'.png':'.jpg'),{type:mime});}finally{image.close();}}
async function upload(item:Pending){item.status='uploading';item.error='';report();try{const file=await stripMetadata(item.file);const body=new FormData();body.append('file',file);body.append('usage',props.usage);const asset=await post<FileAsset>('/files',body);newlyUploaded.add(asset.id);emit('update:modelValue',[...props.modelValue,asset]);URL.revokeObjectURL(item.url);pending.value=pending.value.filter(p=>p.id!==item.id);}catch(e){item.status='failed';item.error=errorText(e);}finally{report();}}
async function choose(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';if(files.length+props.modelValue.length+pending.value.length>6){notify('每组最多上传6张图片，请减少选择数量','error');return;}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)){notify('仅支持不超过10MB的JPG、PNG或WebP图片','error');return;}for(const file of files){const item:Pending={id:crypto.randomUUID(),file,url:URL.createObjectURL(file),status:'waiting',error:''};pending.value.push(item);report();await upload(pending.value[pending.value.length-1]!);}}
function removePending(item:Pending){URL.revokeObjectURL(item.url);pending.value=pending.value.filter(p=>p.id!==item.id);report();}
async function remove(asset:FileAsset){try{if(newlyUploaded.has(asset.id))await request(`/files/${asset.id}`,{method:'DELETE'});emit('update:modelValue',props.modelValue.filter(a=>a.id!==asset.id));}catch(e){notify(errorText(e),'error');}}
onBeforeUnmount(()=>pending.value.forEach(p=>URL.revokeObjectURL(p.url)));
</script>
<template><div><p style="margin-bottom:7px">{{usage==='RESULT'?'处理结果图片':'现场图片'}}</p><div class="upload-area"><input type="file" aria-label="选择图片" accept="image/jpeg,image/png,image/webp" multiple :disabled="disabled||modelValue.length+pending.length>=6" @change="choose"><p class="form-note" style="margin-bottom:0">JPG / PNG / WebP · 最多6张，每张≤10MB。上传前缩放并去除元数据。</p></div><div class="upload-items"><div v-for="asset in modelValue" :key="asset.id" class="upload-item"><a :href="asset.url" target="_blank"><img :src="asset.thumbnailUrl" :alt="asset.originalName"></a><div><p>{{asset.originalName}}</p><small>上传成功</small></div><button type="button" :disabled="disabled" @click="remove(asset)">移除</button></div><div v-for="item in pending" :key="item.id" class="upload-item"><img :src="item.url" :alt="item.file.name"><div><p>{{item.file.name}}</p><small :class="{'field-error':item.status==='failed'}">{{item.status==='waiting'?'等待上传':item.status==='uploading'?'处理并上传中…':item.error}}</small></div><button v-if="item.status==='failed'" type="button" @click="upload(item)">重试</button><button type="button" :disabled="item.status==='uploading'" @click="removePending(item)">移除</button></div></div></div></template>
